import numpy as np


def most_similar_index(documents, query):
    if not documents or not query:
        return -1
    q = np.asarray(query, dtype=float)
    if float(np.linalg.norm(q)) == 0.0:
        return -1
    best_index = -1
    best_distance = None
    for index, document in enumerate(documents):
        d = np.asarray(document, dtype=float)
        if float(np.linalg.norm(d)) == 0.0:
            continue
        distance = float(np.linalg.norm(d - q))
        if best_distance is None or distance < best_distance:
            best_distance = distance
            best_index = index
    return best_index
